<?php
/**
 * Bundled starter configuration for Quote System.
 *
 * The payloads are compressed only to keep the plugin source compact.
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function qs_setup_decode_payload( $encoded ) {
	$decoded = base64_decode( $encoded, true );
	if ( false === $decoded ) {
		return array();
	}
	$json = @gzuncompress( $decoded );
	if ( ! is_string( $json ) ) {
		return array();
	}
	$data = json_decode( $json, true );
	return is_array( $data ) ? $data : array();
}

function qs_setup_default_products() {
	return qs_setup_decode_payload( '' );
}

function qs_setup_acf_field_groups() {
	return qs_setup_decode_payload( '' );
}
